const root = $json.body ?? $json;
if (!root || root.object !== 'whatsapp_business_account' || !Array.isArray(root.entry)) throw new Error('malformed_meta_payload');
const events = [];
for (const entry of root.entry) {
  for (const change of (entry.changes || [])) {
    if (change.field !== 'messages' || !change.value || !change.value.metadata) continue;
    const value = change.value;
    const metadata = value.metadata;
    const phone = String(metadata.phone_number_id || '');
    if (phone !== '1061851020353611') throw new Error('wrong_phone_number_id');
    const contacts = Object.fromEntries((value.contacts || []).map(c => [String(c.wa_id || ''), c]));
    for (const status of (value.statuses || [])) {
      if (!['sent', 'delivered', 'read', 'failed'].includes(status.status) || !status.id || !status.recipient_id || status.timestamp == null) throw new Error('malformed_status');
      events.push({json: {kind: 'status', status: status.status, wamid: String(status.id), external_message_id: String(status.id), recipient_id: String(status.recipient_id), timestamp: String(status.timestamp), phone_number_id: phone, correlation_id: `${String(entry.id || 'entry')}:${String(status.id)}`}});
    }
    for (const message of (value.messages || [])) {
      if (!message.id || !message.from || message.timestamp == null) throw new Error('malformed_message');
      const base = {kind: 'message', external_message_id: String(message.id), external_actor_id: String(message.from), wa_id: String(contacts[String(message.from)]?.wa_id || message.from), message_type: String(message.type || 'unknown'), received_at: new Date(Number(message.timestamp) * 1000).toISOString(), correlation_id: `${String(entry.id || 'entry')}:${String(message.id)}`, phone_number_id: phone, display_phone_number: String(metadata.display_phone_number || '')};
      if (message.type !== 'text') { events.push({json: {...base, kind: 'unsupported', response_text: 'Por ahora puedo procesar mensajes de texto. Escribime tu consulta en un mensaje de texto.'}}); continue; }
      if (!message.text || typeof message.text.body !== 'string' || !message.text.body.trim()) throw new Error('empty_text');
      events.push({json: {...base, kind: 'text', schema_version: 'OMEGA_CHANNEL_MESSAGE_V1', channel: 'whatsapp', message_type: 'text', text: message.text.body.trim().slice(0, 500), channel_metadata: {provider: 'meta_cloud_api', phone_number_id: phone}}});
    }
  }
}
if (!events.length) throw new Error('no_supported_event');
return events;

const crypto = require('crypto');
const source = $json;
const payload = {schema_version: 'OMEGA_CHANNEL_MESSAGE_V1', channel: 'whatsapp', external_message_id: source.external_message_id, external_actor_id: source.external_actor_id, message_type: 'text', text: source.text, received_at: source.received_at, correlation_id: source.correlation_id, channel_metadata: {provider: 'meta_cloud_api', phone_number_id: source.phone_number_id}};
const body = JSON.stringify(payload);
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomUUID();
const secret = $env.OMEGA_CHANNEL_INGRESS_SECRET;
if (!secret) throw new Error('omega_ingress_secret_missing');
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}\n${nonce}\n${body}`).digest('hex');
return [{json: {...source, omega_body: body, omega_headers: {'X-Omega-Service': 'n8n-whatsapp-staging', 'X-Omega-Timestamp': timestamp, 'X-Omega-Nonce': nonce, 'X-Omega-Signature': signature, 'X-Omega-Idempotency-Key': source.external_message_id}}}];

const source = $('Sign OMEGA Channel Request').item.json;
const result = $json;
if (result.deduplicated === true) return [{json: {skip_outbound: true, external_message_id: source.external_message_id}}];
const text = result.response?.text;
if (!result.ok || typeof text !== 'string' || !text) throw new Error('omega_response_invalid');
return [{json: {skip_outbound: false, external_message_id: source.external_message_id, external_actor_id: source.external_actor_id, phone_number_id: source.phone_number_id, response_text: text}}];

if ($json.skip_outbound) return [{json: $json}];
const capture = $env.META_OUTBOUND_CAPTURE_URL;
const graphBase = $env.META_GRAPH_BASE_URL || 'https://graph.facebook.com';
const token = $env.META_ACCESS_TOKEN;
const base = capture || graphBase;
if (!base || !token) return [{json: {...$json, skip_outbound: true}}];
const path = `/v25.0/${$json.phone_number_id}/messages`;
return [{json: {...$json, meta_request: {method: 'POST', url: base.replace(/\/$/, '') + path, graph_url: `https://graph.facebook.com${path}`, headers: {Authorization: `Bearer ${token}`, 'Content-Type': 'application/json'}, body: {messaging_product: 'whatsapp', recipient_type: 'individual', to: $json.external_actor_id, type: 'text', text: {body: $json.response_text}}}}}];

const body = $json;
const wamid = body.messages?.[0]?.id || body.wamid || null;
return [{json: {status: 'outbound_intercepted', wamid, response_parsed: true}}];
